public class InvocationMatcher_captureArgumentsFrom_TriageGen0Test {

    // Mock implementation of CapturesArguments to verify behavior
    private static class TestCapturesArguments implements Matcher, CapturesArguments {
        Object capturedValue = null;
        int callCount = 0;

        @Override
        public void captureFrom(Object argument) {
            this.capturedValue = argument;
            this.callCount++;
        }

        @Override
        public boolean matches(Object argument) {
            return true;
        }
    }

    // Mock implementation of a regular Matcher that does NOT implement CapturesArguments
    private static class RegularMatcher implements Matcher {
        @Override
        public boolean matches(Object argument) {
            return true;
        }
    }

    @Test
    public void testCaptureArgumentsFrom_AllMatchersAreCapturing() {
        Invocation i = mock(Invocation.class);
        Object arg1 = "first";
        Object arg2 = "second";
        when(i.getArguments()).thenReturn(new Object[]{arg1, arg2});

        TestCapturesArguments m1 = new TestCapturesArguments();
        TestCapturesArguments m2 = new TestCapturesArguments();
        List<Matcher> matchers = Arrays.asList(m1, m2);

        // Using reflection or a way to instantiate since we don't have the real InvocationMatcher internals easily
        // But based on the provided signature:
        InvocationMatcher matcher = new InvocationMatcher(i, matchers);

        matcher.captureArgumentsFrom(i);

        assertEquals(arg1, m1.capturedValue);
        assertEquals(1, m1.callCount);
        assertEquals(arg2, m2.capturedValue);
        assertEquals(1, m2.callCount);
    }

    @Test
    public void testCaptureArgumentsFrom_MixedMatchers() {
        Invocation i = mock(Invocation.class);
        Object arg0 = "zero";
        Object arg1 = "one";
        Object arg2 = "two";
        when(i.getArguments()).thenReturn(new Object[]{arg0, arg1, arg2});

        TestCapturesArguments m0 = new TestCapturesArguments(); // Captures
        RegularMatcher m1 = new RegularMatcher();            // Does not capture
        TestCapturesArguments m2 = new TestCapturesArguments(); // Captures

        List<Matcher> matchers = Arrays.asList(m0, m1, m2);
        InvocationMatcher matcher = new InvocationMatcher(i, matchers);

        matcher.captureArgumentsFrom(i);

        // m0 should get arg0
        assertEquals(arg0, m0.capturedValue);
        assertEquals(1, m0.callCount);

        // m1 is skipped (no capture logic)

        // m2 should get arg2 (index k=2)
        assertEquals(arg2, m2.capturedValue);
        assertEquals(1, m2.callCount);
    }

    @Test
    public void testCaptureArgumentsFrom_EmptyMatchers() {
        Invocation i = mock(Invocation.class);
        when(i.getArguments()).thenReturn(new Object[]{});

        List<Matcher> matchers = new ArrayList<>();
        InvocationMatcher matcher = new InvocationMatcher(i, matchers);

        // Should not throw exception
        matcher.captureArgumentsFrom(i);
        assertEquals(0, matchers.size());
    }

    @Test
    public void testCaptureArgumentsFrom_NoCapturingMatchers() {
        Invocation i = mock(Invocation.class);
        when(i.getArguments()).thenReturn(new Object[]{"data"});

        RegularMatcher m = new RegularMatcher();
        List<Matcher> matchers = Arrays.asList(m);
        InvocationMatcher matcher = new InvocationMatcher(i, matchers);

        // Should complete without error
        matcher.captureArgumentsFrom(i);
    }

